// Definition for a binary tree node.
// class TreeNode {
//     int val;
//     TreeNode left;
//     TreeNode right;
//     TreeNode(int x) { val = x; }
// }
public TreeNode buildTree(int[] preorder, int[] inorder) {
    return build(preorder, 0, preorder.length - 1, inorder, 0, inorder.length - 1);
}

private TreeNode build(int[] preorder, int preLo, int preHi,
                       int[] inorder, int inLo, int inHi) {
    if (preLo > preHi) {
        return null;
    }
    int rootVal = preorder[preLo];
    TreeNode root = new TreeNode(rootVal);
    int mid = inLo;
    while (inorder[mid] != rootVal) {
        mid++; // linear scan → O(n) per call
    }
    int leftSize = mid - inLo;
    root.left = build(preorder, preLo + 1, preLo + leftSize, inorder, inLo, mid - 1);
    root.right = build(preorder, preLo + leftSize + 1, preHi, inorder, mid + 1, inHi);
    return root;
}

// Definition for a binary tree node.
// class TreeNode {
//     int val;
//     TreeNode left;
//     TreeNode right;
//     TreeNode(int x) { val = x; }
// }
private int preIndex;
private Map<Integer, Integer> inIndex;

public TreeNode buildTree(int[] preorder, int[] inorder) {
    preIndex = 0;
    inIndex = new HashMap<>();
    for (int i = 0; i < inorder.length; i++) {
        inIndex.put(inorder[i], i);
    }
    return build(preorder, 0, inorder.length - 1);
}

private TreeNode build(int[] preorder, int inLo, int inHi) {
    if (inLo > inHi) {
        return null;
    }
    int rootVal = preorder[preIndex++];
    TreeNode root = new TreeNode(rootVal);
    int mid = inIndex.get(rootVal);
    root.left = build(preorder, inLo, mid - 1);   // left BEFORE right
    root.right = build(preorder, mid + 1, inHi);
    return root;
}

